import React, { useState, useContext, useEffect } from 'react';
import { AuthContext } from '../context/AuthContext';

const ModificarDatosPage = () => {
  const { user, updateUser } = useContext(AuthContext);
  
  // Inicializa el estado con los datos del usuario
  const [name, setName] = useState(user ? user.name : '');
  const [location, setLocation] = useState(user ? user.location : '');

  // Efecto para actualizar el estado si el usuario cambia
  useEffect(() => {
    if (user) {
      setName(user.name);
      setLocation(user.location);
    }
  }, [user]);

  const handleSave = () => {
    updateUser({ name, location }); // Actualiza los datos del usuario
    alert('Datos guardados');
  };

  return (
    <div className='contenedorModificarDatos'>
      <h1 className='tituloModificar'>Datos personales</h1>
      <input
        type='text'
        placeholder='NOMBRE'
        value={name}
        onChange={(e) => setName(e.target.value)} // Actualiza el estado al cambiar el input
      />
      <input
        type='text'
        placeholder='LOCALIDAD'
        value={location}
        onChange={(e) => setLocation(e.target.value)} // Actualiza el estado al cambiar el input
      />
      <button onClick={handleSave}>Guardar</button>
    </div>
  );
};

export default ModificarDatosPage;
